<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('installations.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'installations');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='create'){$pid=fint('project_id');$p=db_one($pdo,'SELECT site_address FROM projects WHERE id=?',[$pid]);$pdo->prepare('INSERT INTO installations(installation_code,project_id,scheduled_start,scheduled_end,status,site_address,team_lead_id,tools_notes,installation_notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([op_code('INS'),$pid,fpost('scheduled_start'),fpost('scheduled_end')?:null,'scheduled',$p['site_address']??null,fint('team_lead_id'),fpost('tools_notes')?:null,fpost('installation_notes')?:null,$staff['id']]);flash('success','Installation scheduled.');}elseif($a==='status'){$pdo->prepare('UPDATE installations SET status=?,completed_at=IF(?="completed",NOW(),completed_at) WHERE id=?')->execute([fpost('status'),fpost('status'),fint('id')]);flash('success','Installation updated.');}staff_redirect('staff/pages/installations.php');}
$projects=project_options($pdo);$staffs=staff_options($pdo);$rows=db_rows($pdo,'SELECT i.*,p.project_code,p.name project_name,c.name customer_name,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) team_lead FROM installations i JOIN projects p ON p.id=i.project_id JOIN customers c ON c.id=p.customer_id LEFT JOIN staff s ON s.id=i.team_lead_id ORDER BY i.scheduled_start');$pageTitle='Installation Scheduling';require __DIR__.'/../../includes/staff/header.php';module_head('Field Work','Installation Scheduling','Coordinate dates, teams, site details and completion.');?>
<section class="staff-panel"><form method="post" class="mini-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Project<select name="project_id" required><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Start<input type="datetime-local" name="scheduled_start" required></label><label>End<input type="datetime-local" name="scheduled_end"></label><label>Team lead<select name="team_lead_id"><option value="">Unassigned</option><?php foreach($staffs as $s):?><option value="<?=$s['id']?>"><?=hopt($s['first_name'],$s['last_name'])?></option><?php endforeach?></select></label><label>Tools<input name="tools_notes"></label><button class="btn primary">Schedule</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Date</th><th>Project</th><th>Customer</th><th>Team lead</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h(date('j M Y, g:i A',strtotime($r['scheduled_start'])))?></b></td><td><?=h($r['project_code'].' · '.$r['project_name'])?></td><td><?=h($r['customer_name'])?></td><td><?=h($r['team_lead']?:'Unassigned')?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['scheduled','confirmed','in_progress','completed','postponed','cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><button class="btn">Save</button></form></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>